INSERT INTO match_game_setups VALUES(1,'FC26','4-2-3-1 Wide','Counter','Balanced',45,NULL,1,'PSG전 한 경기 재현용. 낮은 점유에서 탈취 직후 적은 패스로 Madjo와 우측 McGinn을 찾은 직접 전환은 Counter에 대응한다. 중앙을 좁게 보호한 4-2-3-1/일시적 5-4-1과 스코어에 따른 라인 상승을 하나의 정적 설정으로 근사하기 위해 Balanced·45를 채택했다. 0-0과 1-2의 라인 높이 차이는 이 단일 프리셋이 완전히 담지 못한다.','SofaScore event 16260286; match_reports.id=1; El País·AS 경기 분석; Emery 경기 후 기자회견','MEDIUM — 선수 역할은 단일 경기 실측 커널, 팀 설정은 90분 지배적 패턴의 게임 번역. 실제 게임 내 tactic_code 미검증');
INSERT INTO match_game_setups VALUES(2,'FC26','3-4-2-1','Balanced','Balanced',55,'',1,unistr('AC 밀란전 한 경기 재현용. 점유 시 3-2-5로 백3(아체암퐁·포파나·하토) 앞에 피벗 2, 양 윙백(팔레스트라 좌·네투 우)이 동시에 극단 전진했다 — 실측 avg_x가 포파나 31.3 < 아체암퐁 43.0 ≈ 하토 43.5 < 네투 59.8 < 팔레스트라 65.9로 이를 지지한다. 비점유는 밀란을 후방·측면으로 몰아 라인 브레이킹을 봉쇄해 유효슈팅 0을 만들었다. 점유 50%·빅찬스 7-0의 균형을 Balanced·55로 근사했다. ⛔ 시즌 정본(백4)과 분리된 MATCH ONLY 설정이다 — obs#209·#217 참조.\u000a⚠️ **[2026-08-19 정정]** 위 「시즌 정본(백4)과 분리된」은 **당시 DB 상태와 어긋난다** — `team_tactic_setups` id=15의 `formation`은 그때도 **3-4-2-1(백3)** 이었다. 08-12에 기록된 「가설 A(3-4-2-1) / 가설 B(4-2-3-1)」 병기를 정본이 백4인 것으로 읽은 결과로 보인다. ⚠️ 또한 이 프리셋의 `formation`=3-4-2-1 + LDM/RDM(`dm_dlp`) 조합은 **FC26에 존재하지 않는다**(obs#254). 시즌 정본은 5-4-1로 정합했고 이 경기 전용 행은 **미정합 이월**이다.'),'FotMob matchDetails 5739312 + SofaScore event 16285002; match_reports.id=2; 첼시 공식 매치리포트; Yahoo/Futbol Chronicle 2026-08-10','MEDIUM — 포메이션·좌우는 실측 avg_x/avg_y가 직접 지지한다. 팀 설정(빌드업·라인)은 90분 지배 패턴의 게임 번역이며 tactic_code 미검증. ⚠️ 프리시즌 표본');
INSERT INTO match_game_setups VALUES(3,'FC26','4-2-3-1 Wide','Balanced','High',65,'',1,unistr('AS 모나코전 한 경기 재현용. 4-2-3-1 골격에 연쇄형 압박 트리거(소보슬라이·프림퐁이 걸면 나머지가 뒤 공간을 덮는다)와 이중 빌드업 모드(참을성 있는 점유 + 저위치 롱볼)가 함께 관측됐다. 점유 52%·상대 박스 터치 32-24로 전진은 됐으나 88분 코너 실점으로 끝났다. 이라올라의 하이라인 기조를 High·65로 두되, 감독 본인이 후반 붕괴 원인을 ''90분을 버틸 체력이 없다''로 지목한 만큼 이 단일 프리셋은 전·후반 차이를 담지 못한다. ⚠️ 풀백 전진이 비대칭이었다 — 프림퐁 avg_x 53.4 vs 치미카스 42.1·케르케즈 41.9로 우측만 올라갔다.\u000a\u000a[2026-08-25 버그 수정] ⚠️ `formation` 필드가 `slots.formation`과 문자열이 달라 site/report.html의 재현 프리셋 x/y JOIN(`core/export.py` game_players)이 전원 실패하고 있었다 — LIV 26/27 실제 운용은 ''4-2-3-1 Wide''(slots 정본)인데 이 행엔 ''Wide'' 없이 저장돼 있었다. 포메이션 실체 변경 없음, 표기만 slots 정본과 일치시켰다.'),'FotMob matchDetails 5765326 + SofaScore event 16284988; match_reports.id=3; liverpoolfc.com 이라올라 경기 후 전문 2026-08-09','MEDIUM — 포메이션·비대칭은 실측이 지지한다. 압박 서술의 원문은 403으로 본문 미확보(검색 인덱스 요약)라 팀 설정의 압박 축은 근거가 약하다. tactic_code 미검증');
INSERT INTO match_game_setups VALUES(4,'FC26','4-4-2','Counter','Deep',35,'',1,'바이에른전 한 경기 재현용. 서사가 일관되게 ''압박을 흡수하도록 세웠다''·''형태 없는 로우 블록''으로 기록하고, 실측도 태클 30(상대 22)·클리어 16·점유 44%로 그 방향이다. 82분까지 후반 첫 유효 기회가 없었고 83분 고메스 득점은 박스 외곽 원거리 슛이었다 — 전진 산출이 거의 없던 경기라 Counter·Deep·35로 근사했다. ⚠️ 선발이 부분 B팀이고(주력 3인은 4주 휴가 정책으로 결장) 피치가 손상 상태였다 — 이 프리셋을 정본 근거로 쓰지 말 것.','FotMob matchDetails 5449690 + SofaScore event 16284981; match_reports.id=4; Bavarian Football Works 2026-08-08','MEDIUM-LOW — 팀 설정은 상대·중립 매체 서사의 게임 번역이고 빌라 전담 기자 리포트는 확보 실패했다. 포메이션 4-4-2는 FotMob away formation과 positionId 배열 양쪽으로 확인. tactic_code 미검증');
INSERT INTO match_game_setups VALUES(20,'FC26','4-2-3-1 Wide','Counter','Balanced',50,NULL,1,unistr('코모 2차전(안필드) 한 경기 재현용. 빌드업 **Counter**: 패스 376(상대 540)인데 파이널서드 진입 49-31이고 파이널서드 패스 성공률은 64%(상대 80%)다 — 적은 패스로 더 자주 전방에 도달하는 직선 경로이며 롱볼 37시도(46%)·크로스 18시도(22%)가 그 수단이다. 두 골 모두 측면 크로스에서 나왔다. 수비 **Balanced**·라인 **50**: 태클 22·지상경합 60%로 적극 개입하지만 인터셉트는 4에 그치고 상대 박스 터치 31·슈팅 14·코너 8을 허용해 블록이 높지 않았다 — High도 Deep도 아니다. ⚠️ 직전 모나코전 프리셋(Balanced/High/65)보다 **한 칸 낮다**: 같은 체제 안의 경기별 차이이고 상대(코모)의 점유 지향 성향이 교란 변수다. 포메이션 4-2-3-1은 LIV 26/27 5경기 전건 동일 라벨이다. ⭐ 정적 설정 하나로 근사할 수 없는 것: 46분 이후 우측 CB가 툴y 35.9→27.6으로 8.3 내려간 전·후반 이분 구조와, 양 풀백이 윙어와 같은 높이까지 올라가 2-4-4가 되는 점유 형태.\u000a\u000a[2026-08-25 버그 수정] ⚠️ `formation` 필드가 `slots.formation`과 문자열이 달라 site/report.html의 재현 프리셋 x/y JOIN(`core/export.py` game_players)이 전원 실패하고 있었다 — LIV 26/27 실제 운용은 ''4-2-3-1 Wide''(slots 정본)인데 이 행엔 ''Wide'' 없이 저장돼 있었다. 포메이션 실체 변경 없음, 표기만 slots 정본과 일치시켰다.'),'SofaScore event 16846122 (lineups·statistics·incidents·average-positions·player heatmap, 수집 2026-08-17 · scripts/collect_sofascore.py) + 다국어 서사 수집 8개 언어권(2026-08-17). 원문 reports/match-watch/2026-08-16-liv-como-2nd-leg.md','MATCH ONLY — 이 경기 재현 전용이며 시즌 prescriptions·slot_canon_roles를 덮지 않는다. ⚠️ 4-2-3-1의 RAM/LAM은 LIV slots 기하에 없어 **RM(x=85)/LM(x=14)** 로 산출했다 — 슬롯 x가 다르면 값이 달라진다(코사인은 x의 계단 함수). ⛔ hp<15인 4명(코우마스·니오니·무뇨스·라이트)은 **fit_sim NULL**이고 역할은 교대한 선수에게서 승계 표기했다 — 실측 근거가 아니라 자리 표시다. ⚠️ trail 국면 0분(리드 편향) · 친선 1경기 · Δ.02~.05는 EA 노이즈(obs#91).');
INSERT INTO match_game_setups VALUES(21,'FC26','4-1-4-1','Short Passing','Balanced',48,NULL,1,'경기 전용 — 시즌 정본(라인 45)보다 **3 높였다**. 이 경기는 홈에서 승격팀 상대로 점유 53%·상대 진영 패스 266 대 180·상대 박스 터치 30 대 19를 기록한 전진 국면이었다. 빌드업 Short Passing은 패스 정확도 88%와 한츠코 91정확패스가 뒷받침한다. ⚠️ 수비 접근 Balanced는 **PPDA 없이** 내린 판단이다. | [2026-08-20 정정] 포메이션 5-4-1 → **4-1-4-1**(Opta). ⭐ 라인 48 판단이 **PPDA 7.77**로 뒷받침된다.','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.');
INSERT INTO match_game_setups VALUES(22,'FC26','4-2-3-1 Wide','Balanced','Deep',38,NULL,1,unistr('점유 27%·상대 진영 패스 83·PPDA 24.69·클리어 23 ⇒ 짧은 패스 점유형이 아니라 밀려난 낮은 블록. 롱볼 37회(성공 35%)가 있어 Short Passing도 아니다 ⇒ Balanced. line_height 38은 백4 avg_x 27~44의 중앙값대에 맞췄다(브라이턴은 같은 지표로 45~56). ⚠️ 50분간 10명 상태의 값이므로 이 프리셋은 "에메리가 의도한 설정"이 아니라 "이 경기에서 실제로 나온 형태"의 재현이다.\u000a\u000a[2026-08-25 버그 수정] ⚠️ `formation` 필드가 `slots.formation`과 문자열이 달라 site/report.html의 재현 프리셋 x/y JOIN(`core/export.py` game_players)이 전원 실패해 선수 칩 11개가 전부 같은(정의되지 않은) 위치에 겹쳐 그려지고 있었다 — AVL의 4-2-3-1 정본 라벨은 ''Wide''가 붙은 ''4-2-3-1 Wide''(slots 정본)다. 포메이션 실체 변경 없음, 표기만 slots 정본과 일치시켰다.'),'FotMob matchDetails matchId=5795369 (curl 200, 2026-08-24) · FotMob shotmap · WhoScored matchCentreData(Opta) matchId=1983554 이벤트 1452건(인앱 브라우저 오리진 fetch) · avfc.co.uk 공식 매치리포트/팀뉴스/1군 스쿼드 페이지(렌더링 본문 직접 확인, 2026-08-23~24) · 스페인어권 종합 보도(검색 요약 기준). ⛔ SofaScore 미사용(obs#290).','measured(match-only). ⚠️ 10명 50분·점유 27% 조건의 값이다. 시즌 team_tactic_setups에 병합 금지.');
INSERT INTO match_game_setups VALUES(23,'FC26','4-2-3-1 Wide','Short Passing','High',72,NULL,1,unistr('점유 61%·패스 445·상대 진영 성공 패스 249·박스 터치 36으로 짧은 패스와 높은 위치를 재현. PPDA 5.95는 압박량 참고치이나 두 차례 전환 실점을 동반했다.\u000a\u000a[2026-08-25 버그 수정] ⚠️ `formation` 필드가 `slots.formation`과 문자열이 달라 site/report.html의 재현 프리셋 x/y JOIN(`core/export.py` game_players)이 전원 실패하고 있었다 — LIV 26/27 실제 운용은 ''4-2-3-1 Wide''(slots 정본)인데 이 행엔 ''Wide'' 없이 저장돼 있었다. 포메이션 실체 변경 없음, 표기만 slots 정본과 일치시켰다.'),'FotMob matchDetails matchId=5795371 (curl, 2026-08-24 수집) — 팀·선수 스탯·평점·분·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983547 이벤트 1412건 (인앱 브라우저) — 좌표·평균위치·5x5 그리드·PPDA / Liverpool FC 공식 리포트·Sky Sports·Guardian·AS·Cadena SER·El País (2026-08-23~24).','measured(match-only). 이 경기 재현값이며 시즌 team_tactic_setups에 병합 금지.');
INSERT INTO match_game_setups VALUES(24,'FC26','4-4-2','Short Passing','Balanced',52,NULL,1,'경기 전용 — R1(라인 48·4-1-4-1)에서 **포메이션과 라인 둘 다 바뀌었다**. 4-4-2는 선발부터이고 주전 라인업 첫 가동이다. Short Passing 근거: 패스 520·정확 459(88%)·파이널서드 진입 56(상대 39). 라인 52 근거: 태클 26회(상대 11)로 볼을 뺏으러 나갔고, El Desmarque(「팀이 매우 전진해 있을 때」)와 Nostresport(「트랜지션에서 취약, 빠른 역습과 직선 질주에 노출」)가 양측에서 같은 그림을 준다. ⚠️ 수비 접근을 Balanced로 유지한 것은 PPDA가 없어 상향 근거가 부족하기 때문이다. ⭐ 보유 국면 실체는 **비대칭 3+1** — 그리말도만 avg_x 54.8로 백4 중 압도적으로 높고 한츠코가 좌측을 커버했다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
INSERT INTO match_game_setups VALUES(25,'FC26','3-4-2-1','Counter','Balanced',50,NULL,1,'점유 38%·패스 389 대 620이라 Short Passing을 기각. xG 2.24(오픈플레이 1.96)·박스 터치 37·전방 3인 직접 결합은 Counter를 지지. PPDA 20.18이라 High를 기각하고 백3 평균 위치·후반 리드 보호를 합쳐 line 50. [08-26 영상 반영, obs#348] Balanced·line 50 재확인 — 트리거 기반 압박(FMS: 10번의 와이드 CB 압박이 피벗 스텝업 트리거, 90분 에너지 아님)·수비 액션 평균 높이 39.8m vs 33.8m(Pedro, FotMob)·5-2-3 협폭 미드블록이 High 기각과 정합. 펜타곤 트랩(중앙 봉쇄→측면 유도)은 Balanced+협폭 구조의 근거. ⚠️ xG는 08-25 D+2 동일 스냅샷 값으로 정정(구 1.70).','FotMob matchDetails matchId=5795372 (curl, 2026-08-25) — 라인업·득점·교체·팀/선수 스탯·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983550 이벤트 1659건 — 터치 좌표·5x5 그리드·PPDA / Chelsea FC 공식 리포트 · Guardian(Jonathan Wilson) · Sky Sports · El País · Cadena SER · AS (2026-08-24~25). / 리포트: reports/match-watch/2026-08-24-che-fulham.md · Guardian 분석 https://www.theguardian.com/football/2026/aug/24/premier-league-chelsea-xabi-alonso-fulham / 영상 전사 8건(2026-08-26, reports/transcripts/)','measured(match-only). 시즌 team_tactic_setups에 병합 금지.');
INSERT INTO match_game_setups VALUES(26,'FC26','3-4-2-1','Counter','Deep',35,NULL,1,'이 경기 전용 프리셋. 첼시 4-3 브라이턴 (PL R3, 홈) — 점유 26%로 이긴 경기: 재시작 무기화와 진입 효율. 근거는 리포트 §7. 시즌 team_tactic_setups·prescriptions·slot_canon_roles를 덮어쓰지 않는다.','SofaScore event 16363249(lineups·average-positions·heatmap·statistics·incidents) + FotMob matchDetails 5795427(xG 4종 동일 스냅샷) + 알론소/휘르첼러 기자회견 1차 + Trivela(브라질, 2026-08-30) + 첼시 공식 매치리포트 + CBS James Benge(08-28·08-30)','측정 + 1차 소스. ⚠️PPDA 미수집. ⚠️제공사 편차: 점유 25.6%(Opta)↔26%, xG 2.97(Opta/SofaScore)↔2.93(FotMob 채택), 패스 성공146(Opta)↔시도227(FotMob). ⚠️단일 경기 fit이 26% 점유로 전 포지션 하향 왜곡됐다 — 시즌 역할 근거로 쓰면 안 된다. ⚠️영상 미수행(경기 전용 전술 분석 영상 부재 + 유튜브 메타데이터 취득 실패) — §2-1a D+1~D+3에서 재시도.');
INSERT INTO match_game_setups VALUES(27,'FC26','4-2-3-1','Short Passing','High',70,NULL,1,'이 경기 전용 프리셋. 첼시 2-0 루턴 (EFL컵 2R, 홈) — 백4 전환과 우측 인사이드-오버랩. 근거는 리포트 §7. 시즌 team_tactic_setups·prescriptions·slot_canon_roles를 덮어쓰지 않는다.','SofaScore event 16798240 + FotMob matchDetails 6005665(xG 4종 동일 스냅샷) + 알론소/잭 윌셔 기자회견 + 첼시 공식 전술 분석(Estêvão POTM) + 442/Perfil·OneFootball-ES(바르코)','측정 + 1차 소스. ⛔선수별 xG·xA 전원 결손 — SofaScore가 EFL컵에 미제공, 0으로 채우지 않았다(docs/30 ①). ⛔PPDA 미수집. ⚠️팀 xG 제공사 편차 큼: FotMob 2.67 ↔ SofaScore 3.27(Δ0.60), §3 규칙대로 FotMob 통일. ⚠️웰벡 골 어시스트는 다수 매체가 에스테방으로 적으나 첼시 공식·실측 모두 구스토다 — 구스토 채택. ⚠️영상 미수행.');
INSERT INTO match_game_setups VALUES(28,'FC26','4-2-3-1','Balanced','Balanced',55,NULL,1,'이 경기 전용 프리셋. 리버풀 2-2 노팅엄 포레스트 (PL R3, 홈) — 69% 점유에 빅찬스 1대5, 이라올라 이식의 첫 반증. 근거는 리포트 §7. 시즌 team_tactic_setups·prescriptions·slot_canon_roles를 덮어쓰지 않는다.','SofaScore event 16363254 + FotMob matchDetails 5795431(xG 4종 동일 스냅샷) + 이라올라/글라스너 기자회견 1차(liverpoolfc.com 전문·Sky) + premierleague.com Alex Keble(2026-06-04) + transferhub 패스 네트워크(2026-08-30) + Eurosport.de/kicker(비르츠 역할 정본) + 헝가리어 nb1.hu·feol.hu(쇼보슬러이 RB 전환)','측정 + 1차 소스. ⛔PPDA 미수집(3회차 연속) — 프록시로 전반 집단 주행 −3km만 확보. ⚠️xG 제공사 편차: 1.75(FotMob 채택) ↔ 1.61(Opta/Sky). ⚠️비르츠 실측 6.4 ↔ ESPN 7·BBC 7·kicker·Sky DE 긍정(어시 1 + 취소골 1 + 유효 헤더 1) — 충돌 기록, 실측 채택하되 산출사 아티팩트 의심. ⚠️자케 8.2는 패스 94회 볼륨 주도값이고 라인 관리 실책 지적이 병존한다. ⚠️쇼보슬러이 fit .567은 71분 이후 RB 전환으로 통합 그리드가 두 역할 평균이 된 결과다 — 「부적합」으로 읽으면 안 된다. ⛔소스 폐기: tacticalfootballanalysis.com이 본머스 승점·순위를 2개 동시에 틀렸다. ⚠️영상 미수행.');
INSERT INTO match_game_setups VALUES(29,'FC26','4-4-2','Balanced','Balanced',50,NULL,1,'이 경기 전용 프리셋. 세비야 1-3 아틀레티코 (라리가 J3, 원정) — 바에나 falso nueve와 33분 안의 3-0. 근거는 리포트 §7. 시즌 team_tactic_setups·prescriptions·slot_canon_roles를 덮어쓰지 않는다.','SofaScore event 16416316 + FotMob matchDetails 5868040(xG 4종 동일 스냅샷) + 시메오네/루이스 가르시아 플라사 기자회견 1차 + 바에나 본인 발언 + El Desmarque·VAVEL·Into the Calderón 우노포르우노 3건 + 101TV(세비야 지역, 상대 관점) + 덴마크어(율만-바리오스 역할 분담 인과) + 슬로바키아어(4-4-2 명시)','측정 + 1차 소스. ⛔PPDA 미수집(ATM 3회차 연속) — 「전환 중심」 주장의 정량 검증 불가. ⛔전술 분석 영상 0건(하이라이트만, 어떤 영상도 시청하지 않았고 리포트에 영상 근거 문장 없음). ⚠️event_id 출처 혼재: ATM 시리즈는 08-19 말라가전이 FotMob(5868012), 08-23·08-29가 SofaScore다. ⚠️바에나 ST fit .499는 부적합이 아니라 역할 정의다 — 다른 슬롯 fit은 LCM .771·RCM .685·LM .583으로 커널이 읽은 실체는 「중앙 미드필더 높이에서 뛰는 공격수」다. ⚠️포메이션 충돌: 실측·슬로바키아·한국·ED 프리뷰 4-4-2 ↔ Infobae/EFE 4-2-3-1 — 실측 채택, Infobae 계열이 R2에 이어 2회 연속 다르게 적는다. ⚠️82분 세비야 PK 클레임은 incidents에 PK 판정이 없어 채택하지 않았다. ⚠️서브에이전트가 보고한 「R2 리포트 바에나 이적료 오기」는 파일 grep 결과 해당 문구가 없어 기각했다. ⛔Marca·AS·Relevo 크롤러 차단.');
INSERT INTO match_game_setups VALUES(30,'FC26','4-2-3-1 Wide','Balanced','Deep',40,NULL,1,'점유 39%·패스 339 대 530(정확도 81% vs 88%)으로 열세. 롱볼 35% 성공(14/40)이 있어 짧은 패스 점유형은 기각하고 Balanced로 둔다. 인터셉트 3회(상대 9회)·태클 20회(파울 17회 동반)로 조직적 차단보다 반응형 몸싸움 수비 — Deep. **PPDA 30.50**(WhoScored/Opta 실측)로 강하게 뒷받침된다. 라인 높이는 백4 avg_x(RCB 린델뢰프 36.1·LCB 토레스 31.2)의 낮은 편에 맞춰 40으로 둔다(브라이턴전 38과 유사하나 그 경기만큼 극단적이지 않음 — 10명·27%점유 이상치가 아니라 11명·39%점유의 통상적 원정 열세).','FotMob matchDetails matchId=5795426 · WhoScored/Opta matchCentreData matchId=1983558','measured(match-only). 시즌 team_tactic_setups에 병합 금지.');
